def _get_stoichiometry(self) -> pd.DataFrame:
        """Build stoichiometric matrix from reactions"""
        build_dict = {}
        for reaction in self.reactions:
            build_dict[reaction.name] = reaction.stoichiometry
        S = pd.DataFrame(build_dict).fillna(value=0)
        return S

