    global_params = {}
    local_params = collections.defaultdict(dict)

    for key in params.keys():
        if re.match("lp_*_", key):
            fkey = key.removeprefix("lp_")
            splitted_list = fkey.split("__") #splits only on the first
            value = params[key]
