def overwrite_y0_dict(y0_dict, dataset):
    """Overwrites the y0 dictionary with the values from the dataset"""
    ynew_dict = y0_dict.copy()
    dataset_iv = dataset.to_dict()

    for met in ynew_dict.keys():
